#!/usr/bin/env bash
# Generated by Github Copilot on behalf of Tim Livingston
# ece-revs.sh — report enclosure-control-engine versions on enclosure hosts
set -euo pipefail

PROG="$(basename "$0")"
CONF_DEFAULT="/etc/dhcp/ansible-enclosure.conf"
CONF="$CONF_DEFAULT"
SSH_USER="root"
SSH_PASSWORD="root"
SSH_TIMEOUT=30
JOBS_DEFAULT=16
JOBS="$JOBS_DEFAULT"
REMOTE_CMD="apt list --installed 2>/dev/null | grep enclosure-control-engine"
ECE_REVS_TMP=""
SPIN_CHARS='|/-\'
SPIN_I=0
UI_LIVE=0
UI_DRAWN=0

usage() {
  cat <<EOF
Usage: ${PROG} [options]

Read enclosure host names from ${CONF_DEFAULT} (ISC DHCP). Host names
carry cluster (c), node (n), rack (r), and enclosure (e) numbers. Only
hosts with an enclosure (e) field are used. Hosts whose names contain
"sw" (switches) are skipped. The list is sorted by c, n, then e.

For each host, SSH as ${SSH_USER} to the DHCP fixed-address IP
(hard timeout ${SSH_TIMEOUT}s) and run:
  ${REMOTE_CMD}

Queries run in parallel (default ${JOBS_DEFAULT} at a time). The table
lists every host immediately and updates in place (no scrolling). The
rightmost column shows waiting, connecting (ASCII spinner | / - \\),
reading, then the package version (or an error). HOST, IP, and status
are not truncated. Rows stay in c/n/e order. Extra columns are added
so the full list fits on the screen.

Options:
  -c, --conf PATH   DHCP config (default: ${CONF_DEFAULT})
  -j, --jobs N      Parallel SSH queries (default: ${JOBS_DEFAULT})
  -h, --help        Show this help and exit

Requires: bash, ssh, sshpass
EOF
}

parse_args() {
  while [[ $# -gt 0 ]]; do
    case "$1" in
      -h|--help)
        usage
        exit 0
        ;;
      -c|--conf)
        [[ $# -ge 2 ]] || { printf '%s: %s requires a path\n' "$PROG" "$1" >&2; exit 2; }
        CONF="$2"
        shift 2
        ;;
      -j|--jobs)
        [[ $# -ge 2 ]] || { printf '%s: %s requires a positive integer\n' "$PROG" "$1" >&2; exit 2; }
        [[ "$2" =~ ^[1-9][0-9]*$ ]] || { printf '%s: invalid jobs count: %s\n' "$PROG" "$2" >&2; exit 2; }
        JOBS="$2"
        shift 2
        ;;
      --)
        shift
        break
        ;;
      -*)
        printf '%s: unknown option: %s\n' "$PROG" "$1" >&2
        usage >&2
        exit 2
        ;;
      *)
        printf '%s: unexpected argument: %s\n' "$PROG" "$1" >&2
        usage >&2
        exit 2
        ;;
    esac
  done
}

# Parse c/n/r/e integers from a hostname. Prints "c n r e" or nothing.
parse_c_n_r_e() {
  local host="$1"
  if [[ "$host" =~ [Cc]([0-9]+)[^0-9]*[Nn]([0-9]+) ]]; then
    local c="${BASH_REMATCH[1]}"
    local n="${BASH_REMATCH[2]}"
    local r=""
    local e=""
    if [[ "$host" =~ [Rr]([0-9]+) ]]; then
      r="${BASH_REMATCH[1]}"
    fi
    if [[ "$host" =~ [Ee]([0-9]+) ]]; then
      e="${BASH_REMATCH[1]}"
    fi
    [[ -n "$e" ]] || return 1
    printf '%s %s %s %s' "$c" "$n" "${r:-0}" "$e"
    return 0
  fi
  return 1
}

# Collect unique enclosure hostnames and IPs from DHCP config, sorted by c, n, e.
# Prints "hostname ip" per line.
list_hosts() {
  local conf="$1"
  local line host="" ip="" parsed c n r e
  declare -A seen=()
  local rows=()

  while IFS= read -r line || [[ -n "$line" ]]; do
    line="${line%%#*}"
    if [[ "$line" =~ ^[[:space:]]*host[[:space:]]+([^[:space:]{]+) ]]; then
      host="${BASH_REMATCH[1]}"
      host="${host%;}"
      ip=""
      continue
    fi
    if [[ "$line" =~ fixed-address[[:space:]]+([0-9]+\.[0-9]+\.[0-9]+\.[0-9]+) ]]; then
      ip="${BASH_REMATCH[1]}"
    fi
    if [[ "$line" =~ \} ]]; then
      if [[ -n "$host" && -n "$ip" && "${host,,}" != *sw* ]]; then
        if parsed="$(parse_c_n_r_e "$host")" && [[ -z "${seen[$host]+x}" ]]; then
          seen[$host]=1
          read -r c n r e <<<"$parsed"
          rows+=("$(printf '%08d %08d %08d %s %s' "$((10#$c))" "$((10#$n))" "$((10#$e))" "$host" "$ip")")
        fi
      fi
      host=""
      ip=""
    fi
  done <"$conf"

  if [[ ${#rows[@]} -eq 0 ]]; then
    return 0
  fi
  printf '%s\n' "${rows[@]}" | sort -k1,1n -k2,2n -k3,3n | awk '{print $4, $5}'
}

extract_version() {
  local text="$1"
  local line ver
  # apt list --installed: enclosure-control-engine/now 1.2.3 amd64 [installed]
  line="$(printf '%s\n' "$text" | awk 'BEGIN{IGNORECASE=1} $1 ~ /enclosure-control-engine\// { print; exit }')"
  if [[ -z "$line" ]]; then
    line="$(printf '%s\n' "$text" | awk 'BEGIN{IGNORECASE=1} /enclosure-control-engine/ { print; exit }')"
  fi
  if [[ -n "$line" ]]; then
    read -r _ ver _ <<<"$line"
    if [[ -n "$ver" && "$ver" != *"/"* ]]; then
      printf '%s' "$ver"
      return 0
    fi
  fi
  line="$(printf '%s\n' "$text" | awk 'BEGIN{IGNORECASE=1} /^[[:space:]]*Version:[[:space:]]*/ { sub(/^[[:space:]]*Version:[[:space:]]*/, ""); print; exit }')"
  if [[ -n "$line" ]]; then
    printf '%s' "$line"
    return 0
  fi
  return 1
}

query_host() {
  local ip="$1"
  local status_file="$2"
  local out="" line rc=0
  local -a runner=(sshpass -e ssh)
  if command -v timeout >/dev/null 2>&1; then
    runner=(timeout --preserve-status --signal=TERM --kill-after=2 "$SSH_TIMEOUT" sshpass -e ssh)
  fi
  printf 'connecting\n' >"$status_file"
  exec 3< <(
    set +e
    SSHPASS="$SSH_PASSWORD" "${runner[@]}" \
      -o StrictHostKeyChecking=no \
      -o UserKnownHostsFile=/dev/null \
      -o GlobalKnownHostsFile=/dev/null \
      -o PreferredAuthentications=password \
      -o PubkeyAuthentication=no \
      -o NumberOfPasswordPrompts=1 \
      -o ConnectTimeout="$SSH_TIMEOUT" \
      -o ConnectionAttempts=1 \
      -o ServerAliveInterval=5 \
      -o ServerAliveCountMax=2 \
      -o BatchMode=no \
      -o LogLevel=ERROR \
      "${SSH_USER}@${ip}" \
      "printf 'ECE_REVS_CONNECTED\\n' >&2; ${REMOTE_CMD}" 2>&1
    printf '__ECE_REVS_RC:%s\n' "$?"
  )
  while IFS= read -r line <&3 || [[ -n "$line" ]]; do
    if [[ "$line" == __ECE_REVS_RC:* ]]; then
      rc="${line#__ECE_REVS_RC:}"
      continue
    fi
    if [[ "$line" == *ECE_REVS_CONNECTED* ]]; then
      printf 'reading\n' >"$status_file"
      continue
    fi
    out+="$line"$'\n'
  done
  exec 3<&-
  if [[ $rc -eq 124 || $rc -eq 137 ]]; then
    printf 'error (timeout %ss)\n' "$SSH_TIMEOUT" >"$status_file"
    return 0
  fi
  local ver
  if ver="$(extract_version "$out")"; then
    printf '%s\n' "$ver" >"$status_file"
    return 0
  fi
  if [[ $rc -ne 0 ]]; then
    printf 'error (ssh/apt rc=%s)\n' "$rc" >"$status_file"
    return 0
  fi
  printf 'error (no enclosure-control-engine in apt list)\n' >"$status_file"
}

ui_term_size() {
  TERM_LINES="${LINES:-}"
  TERM_COLS="${COLUMNS:-}"
  local sz
  if sz="$(stty size 2>/dev/null)"; then
    TERM_LINES="${sz%% *}"
    TERM_COLS="${sz##* }"
  elif command -v tput >/dev/null 2>&1; then
    TERM_LINES="$(tput lines 2>/dev/null || true)"
    TERM_COLS="$(tput cols 2>/dev/null || true)"
  fi
  [[ "$TERM_LINES" =~ ^[1-9][0-9]*$ ]] || TERM_LINES=24
  [[ "$TERM_COLS" =~ ^[1-9][0-9]*$ ]] || TERM_COLS=80
}

status_text() {
  local st="$1"
  if [[ "$st" == connecting ]]; then
    printf 'connecting %s' "${SPIN_CHARS:SPIN_I:1}"
  else
    printf '%s' "$st"
  fi
}

ui_max_status() {
  local i st n max=7
  for ((i = 0; i < TOTAL; i++)); do
    st="$(status_text "${STATUS[i]}")"
    n=${#st}
    (( n > max )) && max=$n
  done
  printf '%s' "$max"
}

ui_max_host() {
  local i n max=4
  for ((i = 0; i < TOTAL; i++)); do
    n=${#HOSTS[i]}
    (( n > max )) && max=$n
  done
  printf '%s' "$max"
}

ui_max_ip() {
  local i n max=2
  for ((i = 0; i < TOTAL; i++)); do
    n=${#IPS[i]}
    (( n > max )) && max=$n
  done
  printf '%s' "$max"
}

ui_cell_w() {
  printf '%s' $((COL_HOST + 1 + COL_IP + 1 + COL_STATUS))
}

ui_layout() {
  ui_term_size
  local header=2 gap=2
  local avail=$((TERM_LINES - header))
  (( avail < 1 )) && avail=1
  local host_need ip_need status_need
  host_need="$(ui_max_host)"
  ip_need="$(ui_max_ip)"
  status_need="$(ui_max_status)"
  local cols
  if [[ $UI_LIVE -eq 1 ]]; then
    cols=$(( (TOTAL + avail - 1) / avail ))
    (( cols < 1 )) && cols=1
  else
    cols=1
  fi
  NCOLS=$cols
  NROWS=$(( (TOTAL + cols - 1) / cols ))
  (( UI_LIVE == 1 && NROWS > avail )) && NROWS=$avail
  UI_ROWS=$((NROWS + header))

  local usable=$TERM_COLS
  if (( NCOLS > 1 )); then
    usable=$(( (TERM_COLS - (NCOLS - 1) * gap) / NCOLS ))
  fi
  (( usable < 8 )) && usable=8
  CELL_W=$usable
  COL_HOST=$host_need
  COL_IP=$ip_need
  COL_STATUS=$status_need
  local natural=$((host_need + 1 + ip_need + 1 + status_need))
  if (( natural <= usable )); then
    COL_HOST=$host_need
    COL_IP=$ip_need
    COL_STATUS=$((usable - host_need - ip_need - 2))
    (( COL_STATUS < status_need )) && COL_STATUS=$status_need
    CELL_W=$((COL_HOST + 1 + COL_IP + 1 + COL_STATUS))
    (( CELL_W > usable )) && CELL_W=$usable
    return 0
  fi
  if (( host_need + 1 + status_need <= usable )); then
    COL_HOST=$host_need
    COL_IP=0
    COL_STATUS=$((usable - host_need - 1))
    CELL_W=$usable
    return 0
  fi
  COL_IP=0
  COL_HOST=$host_need
  if (( COL_HOST + 2 > usable )); then
    COL_HOST=$((usable - 2))
    (( COL_HOST < 4 )) && COL_HOST=4
  fi
  COL_STATUS=$((usable - COL_HOST - 1))
  (( COL_STATUS < 1 )) && COL_STATUS=1
  CELL_W=$usable
}

fmt_cell() {
  local host="$1" ip="$2" st out
  st="$(status_text "$3")"
  if (( COL_IP > 0 )); then
    out="$(printf '%-*.*s %-*.*s %-*.*s' \
      "$COL_HOST" "$COL_HOST" "$host" \
      "$COL_IP" "$COL_IP" "$ip" \
      "$COL_STATUS" "$COL_STATUS" "$st")"
  else
    out="$(printf '%-*.*s %-*.*s' \
      "$COL_HOST" "$COL_HOST" "$host" \
      "$COL_STATUS" "$COL_STATUS" "$st")"
  fi
  printf '%-*.*s' "$CELL_W" "$CELL_W" "$out"
}

fmt_header() {
  local out
  if (( COL_IP > 0 )); then
    out="$(printf '%-*.*s %-*.*s %-*.*s' \
      "$COL_HOST" "$COL_HOST" "$1" \
      "$COL_IP" "$COL_IP" "$2" \
      "$COL_STATUS" "$COL_STATUS" "$3")"
  else
    out="$(printf '%-*.*s %-*.*s' \
      "$COL_HOST" "$COL_HOST" "$1" \
      "$COL_STATUS" "$COL_STATUS" "$3")"
  fi
  printf '%-*.*s' "$CELL_W" "$CELL_W" "$out"
}

ui_hide_cursor() {
  [[ $UI_LIVE -eq 1 ]] || return 0
  printf '\033[?25l'
}

ui_show_cursor() {
  [[ $UI_LIVE -eq 1 ]] || return 0
  printf '\033[?25h'
}

ui_home() {
  [[ $UI_LIVE -eq 1 ]] || return 0
  printf '\033[H'
}

ui_print_line() {
  local text="$1"
  if [[ $UI_LIVE -eq 1 ]]; then
    printf '\r\033[2K%-*.*s\n' "$TERM_COLS" "$TERM_COLS" "$text"
  else
    printf '%s\n' "$text"
  fi
}

ui_draw() {
  local r c i line force="${1:-}"
  ui_layout
  if [[ $UI_LIVE -eq 0 ]]; then
    if [[ $UI_DRAWN -eq 1 && "$force" != force ]]; then
      return 0
    fi
  else
    if [[ $UI_DRAWN -eq 0 ]]; then
      printf '\033[2J'
    fi
    ui_home
  fi

  line=""
  for ((c = 0; c < NCOLS; c++)); do
    (( c > 0 )) && line+="  "
    line+="$(fmt_header HOST IP VERSION)"
  done
  ui_print_line "$line"
  line=""
  for ((c = 0; c < NCOLS; c++)); do
    (( c > 0 )) && line+="  "
    line+="$(fmt_header ---- -- -------)"
  done
  ui_print_line "$line"

  for ((r = 0; r < NROWS; r++)); do
    line=""
    for ((c = 0; c < NCOLS; c++)); do
      i=$((r + c * NROWS))
      (( c > 0 )) && line+="  "
      if (( i < TOTAL )); then
        line+="$(fmt_cell "${HOSTS[i]}" "${IPS[i]}" "${STATUS[i]}")"
      else
        line+="$(printf '%*s' "$CELL_W" '')"
      fi
    done
    ui_print_line "$line"
  done
  UI_DRAWN=1
}

read_status() {
  local i file st
  for ((i = 0; i < TOTAL; i++)); do
    file="$ECE_REVS_TMP/$i"
    [[ -f "$file" ]] || continue
    IFS= read -r st <"$file" || true
    [[ -n "$st" ]] || continue
    STATUS[i]="$st"
  done
}

count_done() {
  local i n=0
  for ((i = 0; i < TOTAL; i++)); do
    case "${STATUS[i]}" in
      waiting|connecting|reading) ;;
      *) n=$((n + 1)) ;;
    esac
  done
  printf '%s' "$n"
}

reap_jobs() {
  local i pid
  for i in "${!PIDS[@]}"; do
    pid="${PIDS[i]}"
    [[ -n "$pid" ]] || continue
    if ! kill -0 "$pid" 2>/dev/null; then
      wait "$pid" || true
      unset 'PIDS[i]'
      inflight=$((inflight - 1))
    fi
  done
}

main() {
  parse_args "$@"

  if [[ ! -r "$CONF" ]]; then
    printf '%s: cannot read %s\n' "$PROG" "$CONF" >&2
    exit 1
  fi
  if ! command -v ssh >/dev/null 2>&1; then
    printf '%s: ssh is required\n' "$PROG" >&2
    exit 1
  fi
  if ! command -v sshpass >/dev/null 2>&1; then
    printf '%s: sshpass is required for password authentication\n' "$PROG" >&2
    exit 1
  fi

  local rows=()
  mapfile -t rows < <(list_hosts "$CONF")
  if [[ ${#rows[@]} -eq 0 ]]; then
    printf '%s: no enclosure hosts (with e) found in %s\n' "$PROG" "$CONF" >&2
    exit 1
  fi

  HOSTS=()
  IPS=()
  STATUS=()
  PIDS=()
  local row host ip
  for row in "${rows[@]}"; do
    [[ -n "$row" ]] || continue
    read -r host ip <<<"$row"
    [[ -n "$host" && -n "$ip" ]] || continue
    HOSTS+=("$host")
    IPS+=("$ip")
    STATUS+=(waiting)
  done
  TOTAL="${#HOSTS[@]}"
  UI_ROWS=0
  if [[ -t 1 ]]; then
    UI_LIVE=1
  fi

  ECE_REVS_TMP="$(mktemp -d "${TMPDIR:-/tmp}/ece-revs.XXXXXX")"
  trap 'ui_show_cursor; [[ ${UI_LIVE:-0} -eq 1 ]] && printf "\033[%s;1H" "$((${UI_ROWS:-0} + 1))"; rm -rf "${ECE_REVS_TMP:-}"' EXIT
  ui_hide_cursor
  ui_draw

  local idx=0 inflight=0
  while (( idx < TOTAL || inflight > 0 )); do
    while (( inflight < JOBS && idx < TOTAL )); do
      query_host "${IPS[idx]}" "$ECE_REVS_TMP/$idx" &
      PIDS[idx]=$!
      inflight=$((inflight + 1))
      idx=$((idx + 1))
    done
    reap_jobs
    read_status
    SPIN_I=$(( (SPIN_I + 1) % ${#SPIN_CHARS} ))
    ui_draw
    if (( idx < TOTAL || inflight > 0 )); then
      sleep 0.1
    fi
  done
  wait || true
  read_status
  ui_draw force
  ui_show_cursor
}

main "$@"

